   &reftitle.examples;


     Пример реализации интерфейса SessionHandlerInterface



     Следующий пример реализует файловое хранилище сессий аналогично обработчику
     сохранения сессий PHP по умолчанию files. Пример легко расширяется
     для хранения сессий в предпочтительной базе данных.



     Обратите внимание на работу с объектно-ориентированным прототипом функции
     session_set_save_handler и регистрацию функции завершения
     через параметр функции — стандартное действие при регистрации
     пользовательского обработчика сессии.




      Для краткости в пример не стали добавлять проверку входных данных.
      Обратите внимание, что параметр $id предоставляется
      пользователем и обязательно проверяется для исключения риска
      атак наподобие обхода путей.
      Поэтому ни в коем случае не переносите код примера в промышленную
       среду, не добавив проверки.




<?php

class MySessionHandler implements SessionHandlerInterface
{
    private $savePath;

    public function open($savePath, $sessionName): bool
    {
        $this->savePath = $savePath;
        if (!is_dir($this->savePath)) {
            mkdir($this->savePath, 0777);
        }

        return true;
    }

    public function close(): bool
    {
        return true;
    }

    #[\ReturnTypeWillChange]
    public function read($id)
    {
        return (string) @file_get_contents("$this->savePath/sess_$id");
    }

    public function write($id, $data): bool
    {
        return file_put_contents("$this->savePath/sess_$id", $data) === false ? false : true;
    }

    public function destroy($id): bool
    {
        $file = "$this->savePath/sess_$id";
        if (file_exists($file)) {
            unlink($file);
        }

        return true;
    }

    #[\ReturnTypeWillChange]
    public function gc($maxlifetime)
    {
        $deleted = 0;
        foreach (glob("$this->savePath/sess_*") as $file) {
            if (filemtime($file) + $maxlifetime < time() && file_exists($file) && unlink($file)) {
                $deleted++;
            }
        }

        return $deleted;
    }
}

$handler = new MySessionHandler();
session_set_save_handler($handler, true);
session_start();

// Продолжаем работать с переменными сессии, устанавливаем или читаем значение из суперглобальной переменной $_SESSION







